import type { Node } from 'acorn';
import type { JsCapabilitiesFile } from '@ohjs/schemas';
import { visit, type AnyNode } from './es5';

/**
 * Built-in API checks driven by `<version>/js-capabilities.json` (generated by schema-extractor from
 * third_party/jerryscript: engine.gni / BUILD.gn / config.h macros and the builtin routine tables).
 * ace-loader adds no polyfills (preset-env without useBuiltIns/core-js), so an API is usable exactly
 * when the engine build has it.
 */
export interface BuiltinEntry {
  /** `Name` for a global, `Owner.name` for a static, `Owner.prototype.name` for a method */
  name: string;
  since: string;
  /** why it is missing on the device, with its source */
  reason: string;
}

interface Index {
  globals: Map<string, BuiltinEntry>;
  statics: Map<string, BuiltinEntry>;
  /** method name → unavailable entries by owner */
  methods: Map<string, BuiltinEntry[]>;
  /** method names available on some probed prototype (used to require an evident receiver type) */
  availableMethods: Map<string, string[]>;
}

const cache = new WeakMap<JsCapabilitiesFile, Index>();

function index(caps: JsCapabilitiesFile): Index {
  let ix = cache.get(caps);
  if (ix) return ix;
  ix = { globals: new Map(), statics: new Map(), methods: new Map(), availableMethods: new Map() };
  for (const a of caps.apis) {
    const parts = a.name.split('.');
    if (a.available) {
      if (parts[1] === 'prototype')
        ix.availableMethods.set(parts[2]!, [...(ix.availableMethods.get(parts[2]!) ?? []), parts[0]!]);
      continue;
    }
    const e: BuiltinEntry = {
      name: a.name,
      since: a.since,
      reason: `${a.reason ?? 'not available'} [${a.source}]`,
    };
    if (parts.length === 1) ix.globals.set(a.name, e);
    else if (parts[1] === 'prototype') ix.methods.set(parts[2]!, [...(ix.methods.get(parts[2]!) ?? []), e]);
    else ix.statics.set(a.name, e);
  }
  cache.set(caps, ix);
  return ix;
}

/** Names of the probed APIs the device engine has / lacks (for tests and docs). */
export function capabilityLists(caps: JsCapabilitiesFile): { available: string[]; unavailable: string[] } {
  return {
    available: caps.apis.filter((a) => a.available).map((a) => a.name),
    unavailable: caps.apis.filter((a) => !a.available).map((a) => a.name),
  };
}

export interface BuiltinFinding {
  entry: BuiltinEntry;
  start: number;
  end: number;
}

function declaredNames(ast: AnyNode): Set<string> {
  const out = new Set<string>();
  const id = (n: unknown): void => {
    const x = n as AnyNode | null | undefined;
    if (x?.type === 'Identifier') out.add(String(x.name));
  };
  visit(ast, undefined, (n) => {
    if (n.type === 'VariableDeclarator' || n.type === 'FunctionDeclaration' || n.type === 'ClassDeclaration')
      id(n.id);
    else if (
      n.type === 'ImportSpecifier' ||
      n.type === 'ImportDefaultSpecifier' ||
      n.type === 'ImportNamespaceSpecifier'
    )
      id(n.local);
    if (
      n.type === 'FunctionDeclaration' ||
      n.type === 'FunctionExpression' ||
      n.type === 'ArrowFunctionExpression'
    )
      for (const p of n.params as unknown[]) id(p);
  });
  return out;
}

function propName(m: AnyNode): string | undefined {
  const p = m.property as AnyNode;
  if (!m.computed && p.type === 'Identifier') return String(p.name);
  if (m.computed && p.type === 'Literal' && typeof p.value === 'string') return p.value;
  return undefined;
}

/**
 * Uses of unavailable built-ins. Globals shadowed by a declaration in the file are skipped. Prototype
 * methods are matched by name on calls (`x.flat()`), except on `this` (ViewModel methods). When the same
 * method name exists on another built-in (`includes` is on String but not on Array), only a receiver whose
 * type is evident counts: an array literal or a variable initialised with one for Array, a string or
 * template literal for String. The same holds for ES5-era method names (`replace`, `match`, `search`,
 * compiled out with RegExp), which app objects such as `router.replace` share.
 */
export function findUnsupportedBuiltins(ast: Node, caps: JsCapabilitiesFile): BuiltinFinding[] {
  const ix = index(caps);
  const root = ast as AnyNode;
  const declared = declaredNames(root);
  const arrays = new Set<string>();
  visit(root, undefined, (n) => {
    const id = n.id as AnyNode | undefined;
    if (
      n.type === 'VariableDeclarator' &&
      id?.type === 'Identifier' &&
      (n.init as AnyNode | null)?.type === 'ArrayExpression'
    )
      arrays.add(String(id.name));
  });
  const ownerOf = (o: AnyNode): string | undefined => {
    if (o.type === 'ArrayExpression' || (o.type === 'Identifier' && arrays.has(String(o.name))))
      return 'Array';
    if (o.type === 'TemplateLiteral' || (o.type === 'Literal' && typeof o.value === 'string'))
      return 'String';
    return undefined;
  };
  const out: BuiltinFinding[] = [];
  visit(root, undefined, (n, parent) => {
    if (n.type === 'Identifier') {
      const e = ix.globals.get(String(n.name));
      if (!e || declared.has(e.name)) return;
      if (parent?.type === 'MemberExpression' && parent.property === n && !parent.computed) return;
      if (parent?.type === 'Property' && parent.key === n && !parent.computed && !parent.shorthand) return;
      if (parent?.type === 'MethodDefinition' || parent?.type === 'PropertyDefinition') return;
      out.push({ entry: e, start: n.start, end: n.end });
    } else if (n.type === 'MemberExpression') {
      const obj = n.object as AnyNode;
      const name = propName(n);
      if (!name) return;
      if (obj.type === 'Identifier' && !declared.has(String(obj.name))) {
        const e = ix.statics.get(`${String(obj.name)}.${name}`);
        if (e) {
          out.push({ entry: e, start: n.start, end: n.end });
          return;
        }
      }
      const missing = ix.methods.get(name);
      if (
        !missing ||
        parent?.type !== 'CallExpression' ||
        parent.callee !== n ||
        obj.type === 'ThisExpression'
      )
        return;
      let entry: BuiltinEntry | undefined = missing[0];
      // ES5-era names (replace, match, search) are common on app objects such as router.replace
      const classic = missing.some((m) => /^ES[1-5]$/.test(m.since));
      if (classic || ix.availableMethods.has(name) || missing.length > 1) {
        const owner = ownerOf(obj);
        entry = owner ? missing.find((m) => m.name.startsWith(`${owner}.prototype.`)) : undefined;
      }
      if (!entry) return;
      const p = n.property as AnyNode;
      out.push({ entry, start: p.start, end: n.end });
    }
  });
  return out.sort((a, b) => a.start - b.start);
}
